// Schema describes shape only - socket is injected by createSocketSdk(socket).
type ChatSchema = {
  chat: {
    messages: {
      $listener: ListenerModel<{
        response: { text: string; user: string };
        topic: "chat/messages";
      }>;
    };
    $roomId: {
      $listener: ListenerModel<{
        response: { text: string; user: string };
        topic: "chat/:roomId";
      }>;
    };
  };
};
```

